      await task.memory?.activate();

      this.logTaskEvent(taskId, 'completed', {
        duration: Date.now() - startTime,
        success: true
      });

      if (task.memory) {
        await task.memory.save();
      }
    } catch (error) {
      this.logTaskEvent(taskId, 'failed', {
        error: error instanceof Error ? error.message : 'Unknown error'
      });
      throw error;
    }
